('wm_manual_pooled.read_public_export_metadata_v2(integer)','f8bf0820d46f446979e7ad359d248f7ff3df52292f59eb8c8eb7d2b5bcc5b587','plpgsql','jsonb',true,'v',ARRAY['search_path=pg_catalog, pg_temp','TimeZone=UTC','DateStyle=ISO,YMD']::text[],true,'{"probin":null,"procost":100,"prokind":"f","proname":"read_public_export_metadata_v2","prorows":0,"pronargs":1,"proconfig":["search_path=pg_catalog, pg_temp","TimeZone=UTC","DateStyle=ISO,YMD"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["byte_limit"],"proargtypes":["23"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}'::jsonb)
 ) pins(signature,body_sha,language,result_type,definer,volatility,configuration,private_helper,metadata) LOOP
  SELECT * INTO original FROM pg_proc WHERE oid=to_regprocedure(dependency.signature);
  IF NOT FOUND THEN RAISE EXCEPTION 'POOLED_LOCAL_PREDECESSOR_MISSING'; END IF;
  IF encode(sha256(convert_to(original.prosrc,'UTF8')),'hex')<>dependency.body_sha
   OR original.proowner<>owner_oid OR original.prokind<>'f' OR original.proisstrict OR original.proleakproof OR original.proparallel<>'u'
   OR original.prolang<>(SELECT oid FROM pg_language WHERE lanname=dependency.language)
   OR pg_get_function_result(original.oid)<>dependency.result_type
   OR original.prosecdef<>dependency.definer OR original.provolatile::text<>dependency.volatility
   OR original.proconfig IS DISTINCT FROM dependency.configuration
   OR (to_jsonb(original)-ARRAY['oid','proowner','prolang','pronamespace','proacl','prosrc']) IS DISTINCT FROM dependency.metadata
   OR EXISTS(SELECT 1 FROM aclexplode(coalesce(original.proacl,acldefault('f',original.proowner))) a
     WHERE a.grantee=0 OR a.grantee<>owner_oid AND (a.is_grantable OR dependency.private_helper))
  THEN RAISE EXCEPTION 'POOLED_LOCAL_PREDECESSOR_DRIFT'; END IF;
  protected_oids:=array_append(protected_oids,original.oid);
 END LOOP;
 SELECT jsonb_agg(CASE WHEN p.proname IN ('store_manual_race_pooled_chain_v1','validate_race_manual_pooled_application_basis_v1') THEN to_jsonb(p)-'prosrc' ELSE to_jsonb(p) END ORDER BY p.oid) INTO original_roster FROM pg_proc p WHERE p.oid=ANY(protected_oids);
 SELECT * INTO STRICT original FROM pg_proc WHERE oid='wm_manual_pooled.lookup(jsonb,text)'::regprocedure;
 before_meta:=to_jsonb(original);
 helper_body:=original.prosrc;
 IF (length(helper_body)-length(replace(helper_body,'PERFORM wm_manual_pooled.check_encoded(e);','')))/length('PERFORM wm_manual_pooled.check_encoded(e);')<>1
 THEN RAISE EXCEPTION 'POOLED_LOCAL_HELPER_PATCH_COUNT'; END IF;
 helper_body:=replace(helper_body,'PERFORM wm_manual_pooled.check_encoded(e);','PERFORM wm_manual_pooled.assert_owner();');
 helper_body:=replace(helper_body,'-- This helper repeats validation per call; no unchecked caller cached handle exists.','-- Owner-private: authoritative caller checked this immutable input in this invocation.');
 lookup_definition:=pg_get_functiondef(original.oid);
 IF (length(lookup_definition)-length(replace(lookup_definition,'wm_manual_pooled.lookup(','')))/length('wm_manual_pooled.lookup(')<>1
 THEN RAISE EXCEPTION 'POOLED_LOCAL_HELPER_NAME_COUNT'; END IF;
 lookup_definition:=replace(lookup_definition,original.prosrc,helper_body);
 lookup_definition:=replace(lookup_definition,'wm_manual_pooled.lookup(','wm_manual_pooled.lookup_validated_local(');
 EXECUTE lookup_definition;
 REVOKE ALL ON FUNCTION wm_manual_pooled.lookup_validated_local(jsonb,text) FROM PUBLIC;
 new_oid:='wm_manual_pooled.lookup_validated_local(jsonb,text)'::regprocedure;
 SELECT * INTO STRICT observed FROM pg_proc WHERE oid=new_oid;
 IF observed.prosrc<>helper_body OR (to_jsonb(observed)-ARRAY['oid','proname','prosrc','proacl']) IS DISTINCT FROM (before_meta-ARRAY['oid','proname','prosrc','proacl'])
  OR EXISTS(SELECT 1 FROM aclexplode(coalesce(observed.proacl,acldefault('f',observed.proowner))) a WHERE a.grantee<>owner_oid)
  OR (SELECT to_jsonb(p) FROM pg_proc p WHERE p.oid=original.oid) IS DISTINCT FROM before_meta
 THEN RAISE EXCEPTION 'POOLED_LOCAL_HELPER_METADATA_CHANGED'; END IF;
 FOR target IN SELECT * FROM (VALUES
 ('public.store_manual_race_pooled_chain_v1(uuid,uuid,uuid,text,jsonb,jsonb,jsonb,jsonb)','$6'),
 ('public.validate_race_manual_pooled_application_basis_v1(jsonb,jsonb,jsonb)','$1')
 ) patch(signature,encoded_arg) LOOP
  SELECT * INTO STRICT original FROM pg_proc WHERE oid=to_regprocedure(target.signature);
  before_meta:=to_jsonb(original); expected_body:=original.prosrc;
  IF (length(expected_body)-length(replace(expected_body,'wm_manual_pooled.lookup('||target.encoded_arg||',','')))/length('wm_manual_pooled.lookup('||target.encoded_arg||',')<>3
   OR (length(expected_body)-length(replace(expected_body,'wm_manual_pooled.check_encoded('||target.encoded_arg||');','')))/length('wm_manual_pooled.check_encoded('||target.encoded_arg||');')<>1
   OR expected_body ~ ('\'||target.encoded_arg||'[[:space:]]*(:=|=)')
  THEN RAISE EXCEPTION 'POOLED_LOCAL_PATCH_COUNT_OR_MUTABLE_INPUT'; END IF;
  expected_body:=replace(expected_body,'wm_manual_pooled.lookup('||target.encoded_arg||',','wm_manual_pooled.lookup_validated_local('||target.encoded_arg||',');
  IF position('wm_manual_pooled.lookup(' IN expected_body)>0
   OR (length(expected_body)-length(replace(expected_body,'wm_manual_pooled.lookup_validated_local('||target.encoded_arg||',','')))/length('wm_manual_pooled.lookup_validated_local('||target.encoded_arg||',')<>3
  THEN RAISE EXCEPTION 'POOLED_LOCAL_PATCH_RESIDUAL'; END IF;
  definition:=pg_get_functiondef(original.oid);
  IF position(original.prosrc IN definition)=0 THEN RAISE EXCEPTION 'POOLED_LOCAL_DEFINITION_MISMATCH'; END IF;
  definition:=replace(definition,original.prosrc,expected_body);
  EXECUTE definition;
  SELECT * INTO STRICT observed FROM pg_proc WHERE oid=original.oid;
  IF observed.prosrc<>expected_body OR (to_jsonb(observed)-'prosrc') IS DISTINCT FROM (before_meta-'prosrc')
  THEN RAISE EXCEPTION 'POOLED_LOCAL_TARGET_METADATA_CHANGED'; END IF;
 END LOOP;
 SELECT jsonb_agg(CASE WHEN p.proname IN ('store_manual_race_pooled_chain_v1','validate_race_manual_pooled_application_basis_v1') THEN to_jsonb(p)-'prosrc' ELSE to_jsonb(p) END ORDER BY p.oid) INTO final_roster FROM pg_proc p WHERE p.oid=ANY(protected_oids);
 IF final_roster IS DISTINCT FROM original_roster THEN RAISE EXCEPTION 'POOLED_LOCAL_PROTECTED_ROSTER_CHANGED'; END IF;
END $migration$;
